import {renderPlanDateStrip,rangeDays} from './plan-date-strip.js';
import {journalVisual} from './journal-visual.js';
import {updateCycleSettings} from './cycle-settings.js';
import {renderTutorialComponents} from './tutorial-components.js';
import {normalizeProductState,cycleGoals,isPantry,pantryIds,pantryStatus,plannerQty,unitInfo,displayQty,stockLabel,mealAdaptation,cookingNeeds,directionOptions,allowsTopUp,candidateAssessment,recipeView,purchaseRows,enterCookingBrowse} from './food-rules.js';
import {basicRecommendations,resolveRecipeCards,rotateRecipeCards,basketPlanningIssue} from './planning.js';
import {ingredients,recipes,styles,substyles,toolsCatalog,newId,newUserState,hasBasketHistory} from './data.js';
import {requirements,totalStock,shortages,commitPurchase,completeMeal,number,eligible} from './domain.js';
import {ai} from './ai.js';
import {flavorArt,glyph,ingredientArt,foodArt,illustration,cookwareArt,cuisineArt,libraryArt,foodAssets} from './assets.js';
const previewSession=new URLSearchParams(location.search).get('previewSession');
const KEY='yilan-v0-state'+(previewSession?':preview:'+previewSession:'');
let state,freshUser=false;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1){state=newUserState();freshUser=true;}}catch{state=newUserState();freshUser=true;}
normalizeProductState(state);
if(freshUser&&!location.hash.startsWith('#/onboarding/'))history.replaceState(null,'','#/login');
let route=location.hash.slice(1)||'/basket',sheet=null,toast='',busy=false,cards=[],journalTab='eaten',stockFilter='全部',search='',wantedFilter='全部',wantedDraft=[],usage=[],saveRecord=true,tradeoffs=[],captureItems=[],captureId=newId(),capturePhoto='',dishDraft={title:'',note:'',saveTo:'eaten',date:new Date().toLocaleDateString('en-CA')},kitchenCandidates=[],adjust=null;
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const action=(a,label,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${a}" ${attrs}>${label}</button>`;
const link=(path,label,cls='')=>`<a class="${cls}" href="#${path}">${label}</a>`;
const integer=(v,min,max)=>{const n=number(v,min,max);if(!Number.isInteger(n))throw new Error('请输入整数');return n;};
const check=(value)=>value?'checked':'';
const date=d=>new Date(d).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});
const recipe=id=>recipes.find(r=>r.id===id);
const icon=ingredientArt;
const chip=(text,a,active)=>action(a,esc(text),'chip'+(active?' active':''),`aria-pressed="${!!active}"`);
function qty(value,field,id,unit='',min=0){const u=unitInfo(state,id);value=Math.round(value/u.size*100)/100;unit=u.unit;return `<div class="qty">${action(`qty|${field}|${id}|-1`,'−','',`aria-label="减少${esc(ingredients[id]?.name||'数量')}"`)}<input class="number" type="number" min="${min}" step="any" value="${value}" aria-label="${esc(ingredients[id]?.name||id)}${field==='usage'?'实际用量':field==='purchase'?'实际购买量':'数量'}" data-field="${field}" data-id="${id}" ${field==='suggestion'&&state.suggestions.find(i=>i.ingredientId===id)?.locked?'disabled':''}>${action(`qty|${field}|${id}|1`,'+','',`aria-label="增加${esc(ingredients[id]?.name||'数量')}"`)}${unit?`<small>${unit}</small>`:''}</div>`;}
const food=foodArt;
function header(title,back=null,right=''){return `<header class="header ${back?'sub':''}">${back?link(back,glyph('arrow-left')+'<span class="sr-only">返回</span>','back'):''}<h1 ${title==='一篮'?'class="brand"':''}>${title}</h1>${right}</header>`;}
const navIcons=['basket','cooking','journal','profile'];
function nav(){return `<nav class="nav" aria-label="主导航" ${sheet?'inert':''}>${[['basket','菜篮'],['cook','做饭'],['journal','食记'],['me','我的']].map(([path,label],i)=>{const active=route==='/'+path;return `<a href="#/${path}" ${active?'class="active" aria-current="page"':''}><span class="nav-icon-container"><img class="nav-handdrawn-icon" src="/assets/library/bottom-nav/nav_${navIcons[i]}_${active?'active':'inactive'}.png" width="34" height="34" alt=""></span><span>${label}</span></a>`;}).join('')}</nav>`;}
const bottom=(label,a,disabled=false)=>`<div class="bottom-action">${action(a,label,'button',disabled||busy?'disabled':'')}</div>`;
function save(next=state){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;}catch{throw new Error('本地保存失败，请释放浏览器存储空间后重试');}}
function notify(message){toast=message;render();setTimeout(()=>{toast='';render();},3800);}
function go(path){if(route===path){render();return;}location.hash=path;}
let tablePage=0;
let aiNotice='',recommendationEpoch=0,rankSignature='',rankedAt=0;
async function refreshCards(force=false){const signature=JSON.stringify([state.cycle,state.wanted.map(w=>[w.id,w.linkedRecipeId]),state.stock,state.pantry,state.diet,state.kitchen,state.meal.selectedRecipeIds,state.meal.diners,state.meal.constraints,state.records.map(r=>r.recipeIds)]);if(!force&&signature===rankSignature&&Date.now()-rankedAt<300000)return;const epoch=++recommendationEpoch,previousFirst=cards[0]?.recipeId;rankSignature=signature;rankedAt=Date.now();const show=out=>{cards=force?rotateRecipeCards(out.recipeCards,previousFirst):out.recipeCards;aiNotice=out.directionMessage||'按这顿想法与家里食材挑选';app.querySelector('.carousel')?.scrollTo({left:0});render();app.querySelector('.carousel')?.scrollTo({left:0});};const immediate=resolveRecipeCards(basicRecommendations(state).recipeCards,state);show(immediate);try{const out=await ai.recommendRecipes(state);if(epoch!==recommendationEpoch)return;show(out);}catch(e){if(epoch!==recommendationEpoch)return;show(immediate);}}

function ingredientTile(id,detail){return `<div class="ingredient-tile">${icon(id)}<h3>${ingredients[id].name}</h3><small>${detail}</small></div>`;}
function basketStartDate(){const saved=new Date(state.cycle.plannedAt||'');return Number.isFinite(saved.getTime())?saved:new Date();}
function basketPeriodLabel(){const start=basketStartDate(),end=new Date(start);end.setDate(end.getDate()+state.cycle.plannedDays-1);const label=d=>`${d.getMonth()+1}月${d.getDate()}日`;return `${label(start)}–${label(end)} · ${state.cycle.plannedDays}天`;}
function basketDateInput(){const d=basketStartDate();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function basket(){const stocked=Object.keys(ingredients).filter(id=>isPantry(id)?pantryStatus(state,id)!=='没有':totalStock(state,id)>0);const filtered=stocked.filter(id=>stockFilter==='全部'||ingredients[id].category===stockFilter);return `<div class="basket-paper-hero">${header('一篮',null,link('/me/settings',glyph('gear')+'<span class="sr-only">设置</span>','action'))}<p class="basket-greeting">好好吃饭，<br>从这一篮开始。</p><img class="basket-window-art" src="/assets/library/basket-window-hero.png" alt="窗边的手绘蔬菜篮"></div><section class="basket-overview"><div class="period"><div class="period-heading"><h3>${basketPeriodLabel()}</h3>${action('edit-cycle','<span aria-hidden="true">✎</span><span class="sr-only">修改本轮安排</span>','period-edit')}</div><div class="cycle-metrics"><div>${glyph('house')}<small>预计在家做</small><b>${state.cycle.expectedMeals}<em>顿</em></b></div><div>${glyph('user')}<small>用餐人数</small><b>${state.profile.defaultDiners}<em>人</em></b></div><div>${glyph('leaf')}<small>饮食偏好</small><b>${esc((state.cycle.goals||[]).join(' · ')||'暂无特别偏好')}</b></div></div></div><div class="action-strip">${link('/basket/shopping',`${glyph('clipboard-text')}<span>查看采购清单</span>${glyph('caret-right')}`)}${link('/basket/plan',`${glyph('plus-circle')}<span>${hasBasketHistory(state)?'再搭一篮':'搭第一篮'}</span>${glyph('caret-right')}`)}</div></section><section class="section"><div class="row between"><h2>优先用这些 <small>（按购入先后）</small></h2></div><div class="stock-attention">${stocked.filter(id=>!isPantry(id)).slice(0,2).map(id=>`<div class="card row">${icon(id)}<div><h3>${ingredients[id].name}</h3><small>剩余 ${stockLabel(state,id)}</small></div></div>`).join('')||'<p class="empty">确认采购后，食材会出现在这里。</p>'}</div></section><section class="section"><div class="row between"><h2>我的食材 <small>(${stocked.length})</small></h2>${link('/basket/capture','＋ 添加食材','text-button')}</div><div class="chips" style="margin-bottom:20px">${['全部','蔬菜','肉类','主食','蛋奶','调味'].map(c=>chip(c,'filter|'+c,stockFilter===c)).join('')}</div><div class="ingredient-grid">${filtered.map(id=>`<button data-action="lots|${id}">${ingredientTile(id,stockLabel(state,id))}</button>`).join('')}</div></section><p class="footer-note">${state.stock.length} 个采购批次 · 数据保存在当前浏览器</p>`;}
function plannerSetup(){const issue=basketPlanningIssue(state);if(!issue)return '';const kitchenReady=recipes.some(r=>eligible(r,{...state,diet:{allergies:[],absoluteAvoids:[]}}));return `<section class="card section" id="planner-setup"><h3>${kitchenReady?'核对饮食限制':'先看看家里用什么做饭'}</h3><p class="note">${esc(issue)}</p>${kitchenReady?link('/me/diet','核对过敏与忌口 ›','text-button'):`<div class="chips section">${toolsCatalog.filter(t=>['wok','stockpot','frying_pan','rice-cooker'].includes(t.id)).map(t=>chip(t.name,'onboard-tool|'+t.id,state.kitchen.tools.some(x=>x.id===t.id&&x.available&&x.quantity>0))).join('')}</div>${link('/me/kitchen','其他厨具与灶位 ›','text-button')}`}</section>`;}
function planWantedRecipes(){return recipes.filter(r=>eligible(r,state)&&foodAssets[r.id]);}
function planWantedCard(r){const w=state.wanted.find(w=>w.linkedRecipeId===r.id),selected=!!w&&state.cycle.anchorWantedDishIds.includes(w.id);return action('plan-want|'+r.id,food(r)+'<span>'+esc(r.name)+'</span><small>'+(selected?'✓ 已选':'＋ 想吃')+'</small>','plan-wanted-card'+(selected?' active':''),`aria-pressed="${selected}" aria-label="${esc(r.name)}"`);}
function planWantedSection(){const available=planWantedRecipes(),featured=available.slice(0,4),selected=state.cycle.anchorWantedDishIds.map(id=>state.wanted.find(w=>w.id===id)).filter(Boolean);return `<section class="plan-wanted"><h2 class="step-title"><b>5</b>特别想吃 <small>（可选）</small></h2><p class="note">看到想吃的就点一下，这一篮优先安排。</p><div class="plan-wanted-grid">${featured.map(planWantedCard).join('')||'<p class="note">先选好家里的厨具，就能看到适合做的菜。</p>'}</div>${selected.length?'<div class="plan-wanted-selected">'+selected.map(w=>action('anchor-remove|'+w.id,esc(w.title)+' ×','chip',`aria-label="取消${esc(w.title)}"`)).join('')+'</div>':''}${action('plan-wanted-more','查看更多菜品','button outline')}</section>`;}
let planDateStart=null;
function plan(){return `${header(hasBasketHistory(state)?'再搭一篮':'搭第一篮','/basket',illustration('decorative','basket_cat','plan-basket'))}${plannerSetup()}<div class="fields"><section><h2 class="step-title"><b>1</b>这次准备多久？</h2>${renderPlanDateStrip(basketDateInput(),state.cycle.plannedDays,planDateStart)}<div class="plan-count-options">${[3,5,7].map(n=>chip(n+'天','cycle|plannedDays|'+n,state.cycle.plannedDays===n)).join('')}<label class="plan-custom-count${[3,5,7].includes(state.cycle.plannedDays)?'':' active'}"><small>自定义</small><input aria-label="自定义天数" type="number" min="1" max="30" inputmode="numeric" value="${state.cycle.plannedDays}" data-field="cycle" data-id="plannedDays"></label></div></section><section><h2 class="step-title"><b>2</b>大约在家做几顿？</h2><div class="plan-count-options">${[2,3,4].map(n=>chip(n+'顿','cycle|expectedMeals|'+n,state.cycle.expectedMeals===n)).join('')}<label class="plan-custom-count${[2,3,4].includes(state.cycle.expectedMeals)?'':' active'}"><small>自定义</small><input aria-label="自定义餐次" type="number" min="1" max="30" inputmode="numeric" value="${state.cycle.expectedMeals}" data-field="cycle" data-id="expectedMeals"></label></div></section><section><div class="row between"><h2 class="step-title"><b>3</b>${hasBasketHistory(state)?'上一篮，还有这些':'家里已有的食材'}</h2><label class="row"><small>带入这一篮</small><input type="checkbox" class="check" data-field="carry" ${check(state.cycle.carryOverEnabled)}></label></div><div class="ingredient-grid">${Object.keys(ingredients).filter(id=>!isPantry(id)&&totalStock(state,id)>0).map(id=>action('carry-item|'+id,ingredientTile(id,stockLabel(state,id)),'carry-choice'+(state.cycle.carryOverEnabled&&!state.cycle.excludedStockIds.includes(id)?' active':''),`aria-pressed="${state.cycle.carryOverEnabled&&!state.cycle.excludedStockIds.includes(id)}" aria-label="本轮使用${ingredients[id].name}" ${!state.cycle.carryOverEnabled?'disabled':''}`)).join('')||'<small>暂无剩余食材</small>'}</div></section><section><h2 class="step-title"><b>4</b>这几天想怎么吃？ <small>（可多选，也可不选）</small></h2><div class="chips">${cycleGoals.map(g=>chip(g,'goal|'+g,state.cycle.goals.includes(g))).join('')}</div></section>${planWantedSection()}<section class="ai-explainer"><h2 class="step-title"><b>6</b>这一篮，会怎样搭配？</h2><p>先用你勾选的食材，照顾特别想吃的，再按这几天的吃法搭配。</p><small>建议可以调整，确认实际购买后才入库。</small></section></div>${bottom(busy?'正在搭配…':'生成这一篮的食材建议 →','generate')}`;}
function recommendation(){const buying=state.suggestions.filter(i=>i.purchaseQty>0);return `${header('为你搭好了这一篮','/basket/plan',glyph('sparkle'))}<p class="note">已结合本轮偏好和现有食材</p><section class="section card"><div class="row between"><h3>${glyph('calendar-blank')} 本轮计划</h3>${link('/basket/plan','编辑','text-button')}</div><div class="summary"><span>${state.cycle.plannedDays} 天</span><span>${state.cycle.expectedMeals} 顿</span><span>${esc((state.cycle.goals||[]).join(' · ')||'暂无特别偏好')}</span></div></section>${tradeoffs.map(t=>`<p class="notice">${esc(t)}</p>`).join('')}<div class="ai-reason"><h3>为什么这样搭</h3>${(state.planningMessages||[]).slice(0,3).map(message=>`<p>${esc(message)}</p>`).join('')||'<p>按人数和餐次准备，用多少买多少。</p>'}</div><h2>本轮建议购买的食材 <small>(${buying.length})</small></h2><div>${buying.map(i=>`<div class="item-row">${icon(i.ingredientId)}<div class="grow"><h3>${ingredients[i.ingredientId].name}</h3><small title="${esc(i.reasonCodes[0])}">${isPantry(i.ingredientId)?pantryStatus(state,i.ingredientId)+' · 按需补一份':'本轮带入 '+displayQty(state,i.ingredientId,i.existingQty)}</small></div>${qty(i.purchaseQty,'suggestion',i.ingredientId,i.unit)}<details class="row-tools"><summary aria-label="${ingredients[i.ingredientId].name}更多操作">${glyph(i.locked?'lock-simple':'dots-three')}</summary><div>${action('lock|'+i.ingredientId,i.locked?'●':'○','text-button',`aria-label="${i.locked?'解锁':'锁定'}${ingredients[i.ingredientId].name}"`)}${action('remove-suggestion|'+i.ingredientId,'×','text-button',`aria-label="删除${ingredients[i.ingredientId].name}" ${i.locked?'disabled':''}`)}</div></details></div>`).join('')}</div>${!buying.length?'<p class="note section">这份清单没有需要购买的项目。</p>':''}${action('suggestion-add','＋ 添加其他食材','add-ingredient') }<div class="bottom-action two">${action('regenerate','重新生成','button outline',busy?'disabled':'')}${buying.length?action('to-shopping','确认这份清单 →','button'):link('/cook','去选这顿想吃的 →','button')}</div>`;}
function shopping(){const pending=state.purchases.filter(p=>p.state!=='stock');return `${header('本轮采购清单','/basket',link('/basket/capture','＋ 顺手买了','action'))}<p class="note">这一篮 · ${state.cycle.plannedDays} 天 · 勾选实际买到的食材</p><div class="tabs"><button class="active">待确认 (${pending.length})</button><button data-action="show-bought">已入库 (${state.purchases.length-pending.length})</button></div>${pending.length?`<div class="purchase-selection row between"><span>已勾选 ${pending.filter(p=>p.checked).length} / ${pending.length} 项</span>${action('purchase-select-all',pending.every(p=>p.checked)?'取消全选':'一键全选','text-button')}</div>`:''}${pending.map(p=>`<div class="item-row">${icon(p.ingredientId)}<label class="grow" for="buy-${p.id}"><h3>${ingredients[p.ingredientId].name}</h3><small>建议 ${displayQty(state,p.ingredientId,p.suggestedQty)}</small></label>${qty(p.actualQty,'purchase',p.ingredientId,p.unit)}<input id="buy-${p.id}" aria-label="已买到${ingredients[p.ingredientId].name}" type="checkbox" class="check" data-field="bought" data-id="${p.id}" ${check(p.checked)}></div>`).join('')||`<div class="empty">本轮采购已确认或尚未生成。<br>${link('/basket/plan',hasBasketHistory(state)?'再搭一篮 →':'搭第一篮 →','text-button')}</div>`}<p class="note section">没买到的保留在清单里。实际购买量可以直接修改。</p>${bottom('完成采购，录入我的食材 →','purchase-review',!pending.some(p=>p.checked))}`;}
function roundTable(selected){const pages=Math.max(1,Math.ceil(selected.length/6));tablePage=Math.max(0,Math.min(tablePage,pages-1));const visible=selected.slice(tablePage*6,tablePage*6+6);return `<div class="round-table ${visible.length>3?'multi-dish-table':''} ${visible.length===4?'four-dish-table':visible.length===5?'five-dish-table':''}"><div class="table-label">${glyph('leaf')} 餐桌（${selected.length} 道）${pages>1?`${action('table-page|-1','‹','text-button',`aria-label="上一桌面" ${tablePage===0?'disabled':''}`)}<small>${tablePage+1}/${pages}</small>${action('table-page|1','›','text-button',`aria-label="下一桌面" ${tablePage===pages-1?'disabled':''}`)}`:''}</div><img class="round-table-art" src="/assets/library/table-final.png" alt="" aria-hidden="true"><div class="table-plates">${visible.map(id=>`<div class="table-dish">${action('heart|'+id,'×','remove',`aria-label="移出圆桌${esc(recipeView(state,id).name)}"`)}${food(recipeView(state,id))}<h3>${esc(recipeView(state,id).name)}</h3></div>`).join('')}${selected.length<3?`<div class="table-dish">${action('browse','＋','empty-plate',`aria-label="继续选菜"`)}<h3>加一道菜</h3></div>`:''}</div></div>${selected.length>=3?action('browse','＋ 继续加菜','text-button table-add-more'):''}`;}
function cook(){const selected=state.meal.selectedRecipeIds;cards=cards.filter(c=>selected.includes(c.recipeId)||candidateAssessment({...state,meal:{...state.meal,selectedRecipeIds:[]}},c.recipeId).allowed);const adaptation=state.meal.state==='cooking'?{adaptations:state.meal.adaptations||[]}:mealAdaptation(state),needs=cookingNeeds(state);const missing=shortages(state,needs);return `${header(glyph('chef-hat')+' 做饭',null,action('adjust','换个方向 '+glyph('arrows-clockwise'),'action'))}<div class="row between cook-context"><small>这一顿 ${state.meal.diners} 人 · ${esc([...(state.meal.constraints.cuisines||[]),...(state.meal.constraints.flavors||[]),state.meal.constraints.mealType==='还没想好'?'':state.meal.constraints.mealType].filter(Boolean).join(' · ')||'按家里食材来')}</small></div><div class="ai-state"><span>${esc(aiNotice)} · ${cards.length} 道</span>${action('retry-ai','再看看','text-button')}</div><div class="carousel" aria-label="候选菜品">${cards.map(c=>{const assessment=candidateAssessment(state,c.recipeId),r=assessment.adaptedRecipes.find(r=>r.baseRecipeId===c.recipeId)||recipeView(state,c.recipeId);return `<article class="food-card">${action('heart|'+c.recipeId,glyph(selected.includes(c.recipeId)?'heart-fill':'heart'),'heart'+(selected.includes(c.recipeId)?' selected':''),` aria-disabled="${!selected.includes(c.recipeId)&&!assessment.allowed}" aria-describedby="dish-status-${c.recipeId}" aria-pressed="${selected.includes(c.recipeId)}" aria-label="${selected.includes(c.recipeId)?'移出':'添加'}${r.name}"`)}${food(r)}<div class="info"><h2>${r.name}</h2><div class="row"><span class="badge">${r.cuisine}</span><small>${r.subtype}</small></div><div class="food-card-status"><small>${glyph('clock')} ${r.totalTime} 分钟</small><small id="dish-status-${c.recipeId}" class="dish-availability" aria-live="polite">${selected.includes(c.recipeId)?'已上桌':!assessment.allowed?(assessment.missing.length?assessment.missing.map(i=>ingredients[i.ingredientId].name).join('、')+'不够，先移出一道菜':'不符合当前厨具或饮食限制'):assessment.missing.length?'补买 '+assessment.missing.map(i=>ingredients[i.ingredientId].name).join('、')+' 后可做':c.shortReason}</small></div></div></article>`;}).join('')||`<div class="empty">${allowsTopUp(state)?'暂时没有补 1–2 样就能完成的菜。可以调整这一顿的选择。':'家里的食材暂时搭不出更多菜，先看看库存，或允许补买 1–2 样。'}${!allowsTopUp(state)?action('allow-top-up','可以补买 1–2 样','text-button'):''}</div>`}</div><p class="cook-swipe-hint">${glyph('hand-swipe-left')}左右滑动切换，点心加入这桌</p>${roundTable(selected)}<div class="card meal-summary"><div class="row between"><h3>已选菜品所需食材 <small>（自动合并）</small></h3><small>${needs.length} 种</small></div><div class="needs">${needs.map(i=>ingredientTile(i.ingredientId,isPantry(i.ingredientId)?pantryStatus(state,i.ingredientId):'需 '+displayQty(state,i.ingredientId,i.qty)+'<br>已有 '+stockLabel(state,i.ingredientId))).join('')||'<small>点菜卡上的心，把想吃的摆上桌。</small>'}</div>${missing.length?allowsTopUp(state)?`<p class="notice">补 ${missing.length} 样就能完成：${purchaseRows(state,needs).map(i=>`${ingredients[i.ingredientId].name} ${displayQty(state,i.ingredientId,i.purchaseQty)}`).join('、')}</p>${missing.length<=2?action('meal-shopping','把需要的加入采购清单 →','link-row text-button'):'<p class="note">超过两样了，换掉一道菜试试。</p>'}`:'<p class="notice">库存或人数有变化，这一桌暂时不够用。可以移出一道菜，或在「换个方向」允许少量补买。</p>':''}${adaptation.adaptations.map(a=>`<p class="note">${esc(a.message)}</p>`).join('')}${adaptation.adaptations.length?'<p class="note">开始做饭即按以上做法，教程和用量会一起调整。</p>':''}${action('start-cooking',busy?'正在编排…':state.meal.state==='cooking'?'继续这餐教程 →':state.meal.state==='completed'?'这餐已完成 · 点心开启下一餐':'开始做饭 →','button',state.meal.state==='completed'||!selected.length||!!missing.length||busy?'disabled':'')}</div>`;}
function tutorial(){const meal=state.meal;if(!meal.plan||!['cooking','completed'].includes(meal.state)||route.split('/').pop()!==meal.id)return `${header('整餐教程','/cook')}<div class="empty">${meal.state==='completed'?'这餐已完成，库存已经扣减。':'先从圆桌选菜并开始做饭。'}</div>${link('/cook','回到做饭','button')}`;return renderTutorialComponents(meal.plan,{diners:meal.diners,completed:meal.state==='completed',quantityLabel:i=>displayQty(state,i.ingredientId,i.qty)});}

function journal(){const eaten=journalTab==='eaten',catalog=recipes.filter(r=>foodAssets[r.id]);const rows=eaten?state.records:state.wanted.filter(w=>!catalog.some(r=>r.id===w.linkedRecipeId));return `<div class="journal-hero">${header('<span class="journal-title">食记</span>',null,link('/journal/camera','▧ 拍照记一道','action'))}<img class="journal-hero-art" src="/assets/library/journal-header.png" alt="手绘食谱与猫咪"></div><div class="tabs journal-tabs">${action('journal-tab|eaten',`吃过的 (${state.records.length})`,eaten?'active':'')}${action('journal-tab|wanted','想吃的',!eaten?'active':'')}</div>${!eaten?'<p class="journal-browse-note">逛逛想吃的，点心收进清单。</p>':''}<div class="journal-grid">${!eaten?catalog.map(r=>{const saved=state.wanted.find(w=>w.linkedRecipeId===r.id);return `<article class="journal-card">${food(r)}${action('want-recipe|'+r.id,glyph(saved?'heart-fill':'heart'),'journal-save'+(saved?' selected':''),`aria-pressed="${!!saved}" aria-label="${saved?'取消想吃':'想吃'}${esc(r.name)}"`)}<div class="info"><h3>${esc(r.name)}</h3><small>${esc(r.cuisine)} · ${r.totalTime} 分钟</small>${saved?action('candidate|'+saved.id,saved.nextBasketCandidate?'✓ 下一篮候选':'标记下一篮','text-button'):'<p class="note">喜欢的话，就记下来。</p>'}</div></article>`;}).join(''):''}${rows.map(r=>`<article class="journal-card">${journalVisual(r)}<div class="info"><h3>${esc(r.title)}</h3><small>${eaten?date(r.eatenAt):'我的想吃清单'}</small>${r.note?`<p class="note">${esc(r.note)}</p>`:''}${eaten?'':action('candidate|'+r.id,r.nextBasketCandidate?'✓ 下一篮候选':'♡ 标记下一篮','text-button')}</div></article>`).join('')}${eaten&&!rows.length?'<div class="empty">做完一餐或拍照，留下第一条食记。</div>':''}</div>`;}

function capture(){const upload=(camera,content,cls)=>`<label class="${cls}">${content}<input type="file" accept="image/*" ${camera?'capture="environment"':''} data-field="photo" data-id="ingredient" aria-label="${camera?'拍摄食材或小票':'从相册选择食材照片'}"></label>`;return `<div class="capture-page">${header('顺手买了','/basket')}<section class="capture-panel"><div class="capture-viewfinder"><i></i><i></i><i></i><i></i>${capturePhoto?`<img class="capture-photo-preview" src="${capturePhoto}" alt="待核对的食材照片">`:`<div class="capture-still-life"><div class="capture-receipt"><b>超市</b>${'<span></span>'.repeat(6)}</div><span class="capture-or">或</span><div class="capture-foods">${icon('lettuce')}${icon('tomato')}${icon('egg')}${icon('milk')}</div></div>`}<h2>拍小票或食材，确认后录入</h2><p class="note">小票、手写清单或单独食材都可以留图</p></div><div class="capture-controls">${upload(false,glyph('clipboard-text')+'<span>从相册选择</span>','capture-upload capture-album')}${upload(true,'<span class="capture-camera-symbol" aria-hidden="true"></span><span class="sr-only">拍摄照片</span>','capture-upload capture-shutter')}${action('capture-tips',glyph('sparkle')+'<span>拍摄小贴士</span>','capture-tips')}</div><p class="capture-status">${capturePhoto?'照片已保存到本次草稿，请手动选择食材并核对数量。':'照片自动识别尚未接入，可先手动添加食材。'}</p></section><section class="capture-results"><div class="row between"><div><h2>${glyph('leaf')} 食材清单</h2><p class="note">${captureItems.length?'共 '+captureItems.length+' 种食材，请确认并编辑':'把这次买到的食材加进来'}</p></div>${action('capture-review','完成','button inline',captureItems.length?'':'disabled')}</div><div class="capture-rows">${captureItems.map((i,n)=>`<div class="capture-item">${icon(i.ingredientId)}<div class="capture-item-name">${action('capture-edit|'+i.id,esc(ingredients[i.ingredientId].name),'capture-kind-button',`aria-haspopup="dialog" aria-label="更换${ingredients[i.ingredientId].name}"`)}<small>${date(new Date())} · ${i.source==='example'?'示例候选':'手动添加'}</small></div><div class="capture-quantity">${action('capture-step|'+n+'|-1','−','',`aria-label="减少${ingredients[i.ingredientId].name}" ${i.actualQty<=unitInfo(state,i.ingredientId).size*(ingredients[i.ingredientId].unit==='克'?50:1)?'disabled':''}`)}<label><input aria-label="候选数量${n+1}" type="number" min="0.01" step="any" value="${Math.round(i.actualQty/unitInfo(state,i.ingredientId).size*100)/100}" data-field="capture-qty" data-id="${n}"><small>${unitInfo(state,i.ingredientId).unit}</small></label>${action('capture-step|'+n+'|1','+','',`aria-label="增加${ingredients[i.ingredientId].name}"`)}</div>${action('capture-remove|'+n,glyph('x'),'capture-delete',`aria-label="删除${ingredients[i.ingredientId].name}"`)}</div>`).join('')||'<p class="empty">还没有添加食材，确认清单后才会入库。</p>'}</div>${action('capture-add','＋ 继续添加','button secondary')}${upload(true,glyph('arrows-clockwise')+' 重新拍摄','capture-upload capture-retake')}<details class="capture-example"><summary>查看示例清单</summary><p class="note">示例不来自照片，不代表实际购买。</p>${action('capture-demo','载入示例','text-button')}</details></section></div>`;}

function camera(){return `${header('拍照记一道','/journal')}<div class="hero-placeholder">📷</div><label class="upload">拍照 / 从相册选择<input type="file" accept="image/*" capture="environment" data-field="photo" data-id="dish" aria-label="选择菜品照片"></label><p class="note section">当前为 Mock 菜名候选；保存前可修改，食记不会扣库存。</p>${action('manual-dish','手动记录一道菜','button secondary')}`;}
function dishConfirm(){return `${header('记录这一餐','/journal/camera')}${capturePhoto?`<img class="preview" src="${capturePhoto}" alt="这一餐">`:food(recipes.find(r=>r.name===dishDraft.title))}<div class="fields section"><label class="field">菜名 *<input data-field="dish" data-id="title" aria-label="菜名" value="${esc(dishDraft.title)}" maxlength="60" placeholder="输入菜名"></label><label class="field">日期 *<input type="date" data-field="dish" data-id="date" value="${esc(dishDraft.date)}"></label><label class="field">备注<textarea data-field="dish" data-id="note" maxlength="300" placeholder="记录做法或下次想调整的地方">${esc(dishDraft.note)}</textarea></label><div class="row"><span>保存到</span>${chip('吃过的','dish-saveTo|eaten',dishDraft.saveTo==='eaten')}${chip('想吃的','dish-saveTo|wanted',dishDraft.saveTo==='wanted')}</div></div>${bottom('保存','save-dish')}`;}
const menu=(path,symbol,title,detail='')=>link(path,`<span>${symbol}</span><span class="grow"><h3>${title}</h3>${detail?`<small>${detail}</small>`:''}</span><span class="arrow">›</span>`,'menu-item');
function me(){return `${header('我的',null,link('/me/settings',glyph('gear')+'<span class="sr-only">设置</span>','action'))}<div class="row"><div class="profile-avatar">♧</div><div class="grow"><h2>${esc(state.profile.nickname)}</h2><small>好好吃饭，好好生活</small></div>${link('/me/profile','编辑资料','text-button')}</div><div class="card cream section"><h3>♧ 好好吃饭 Pro</h3><p class="note" style="margin-top:8px">会员功能暂未开放</p></div>${menu('/me/kitchen','♨','我的厨房',`${state.kitchen.tools.filter(t=>t.available).length} 件可用厨具 · ${state.kitchen.stoveSlots} 个灶位`)}${menu('/me/profile','♧','默认用餐人数',state.profile.defaultDiners+' 人')}${menu('/me/diet','♧','饮食限制','过敏、绝对忌口')}${menu('/me/settings','♧','通用设置','通知、隐私与关于')}<section class="section"><h3>账号与服务</h3>${action('info|会员功能暂未开放','会员与权益 ›','menu-item')}${action('info|一篮 V0：本地浏览器数据；食材规划与菜谱推荐在本地实时计算，无需 API Key；照片识别仍为示例。','帮助与关于 ›','menu-item')}${link('/login','查看欢迎与初始设置 ›','menu-item')}</section>`;}
function profile(onboard=false){if(onboard)return onboardingProfile();return `${header(onboard?'你的做饭情况':'个人资料',onboard?'/login':'/me')}${onboard?'<div class="progress"><i style="width:33%"></i></div>':'<div class="profile-avatar" style="margin:20px auto">♧</div>'}<div class="fields section"><label class="field">昵称<input aria-label="昵称" value="${esc(state.profile.nickname)}" maxlength="30" data-field="profile" data-id="nickname"></label><div><h3 style="margin-bottom:12px">通常几个人吃？</h3><div class="chips">${[1,2,3,4].map(n=>chip(n+' 人','diners|'+n,state.profile.defaultDiners===n)).join('')}</div></div></div>${bottom(onboard?'下一步：看看你的厨房 →':'保存',onboard?'onboard-kitchen':'save-profile')}`;}
function kitchen(onboard=false){if(onboard)return onboardingKitchen();return `${header(onboard?'看看你的厨房':'我的厨房',onboard?'/onboarding/profile':'/me')}<div class="hero-placeholder">♨ 🍳 🪴</div><div class="row between"><div><h2>${state.kitchen.tools.length} <small>件厨具</small></h2></div><label class="row">灶位 <input aria-label="灶位数量" class="number" type="number" min="1" max="4" data-field="stove" value="${state.kitchen.stoveSlots}"></label></div><div class="row section"><label class="upload grow">重新扫描厨房<input type="file" accept="image/*" capture="environment" aria-label="厨房照片" data-field="photo" data-id="kitchen"></label>${link('/me/kitchen/add','＋ 添加厨具','button inline')}</div><div class="tool-grid">${state.kitchen.tools.map(t=>link('/me/kitchen/cookware/'+t.id,`${cookwareArt(t.id)}<h3>${t.name}</h3><small>${t.quantity} 个 · ${t.available?'可用':'已停用'}</small>`,'tool-card'+(!t.available?' off':''))).join('')}</div><p class="note section">推荐和教程会读取当前可用厨具。识别候选必须先核对。</p>${onboard?bottom('下一步：完成设置 →','onboard-complete'):''}`;}
function addTool(){return `${header('添加厨具','/me/kitchen')}<input class="search" placeholder="搜索厨具" data-field="tool-search" value="${esc(search)}"><div class="section">${toolsCatalog.filter(t=>t.name.includes(search)).map(t=>`<div class="item-row">${cookwareArt(t.id)}<div class="grow"><h3>${t.name}</h3><small>加入厨房后可编辑数量</small></div>${action('add-tool|'+t.id,'＋','text-button',`aria-label="添加${t.name}"`)}</div>`).join('')}</div>`;}
function editTool(){const id=route.split('/').pop(),t=state.kitchen.tools.find(t=>t.id===id);if(!t)return `${header('厨具已移除','/me/kitchen')}`;return `${header('编辑厨具','/me/kitchen')}<div class="tool-hero">${cookwareArt(t.id)}</div><h2 style="text-align:center">${t.name}</h2><div class="fields section"><label class="row between">数量<input aria-label="厨具数量" type="number" min="1" max="10" class="number" data-field="tool-qty" data-id="${id}" value="${t.quantity}"></label><label class="row between">是否可用<input type="checkbox" class="check" data-field="tool-available" data-id="${id}" ${check(t.available)}></label><label class="field">备注<input data-field="tool-note" data-id="${id}" value="${esc(t.note||'')}" maxlength="100" placeholder="例如：不粘锅、28cm"></label>${action('delete-tool|'+id,'删除厨具','button danger')}</div>${bottom('保存','save-tool')}`;}
function diet(){return `${header('饮食限制','/me')}<section class="section"><h2>过敏食材</h2><p class="note">将严格排除含这些食材的菜谱</p><div class="chips section">${['花生','海鲜','牛奶','鸡蛋','坚果','小麦','大豆'].map(x=>chip(x,'allergy|'+x,state.diet.allergies.includes(x))).join('')}</div></section><section class="section"><h2>绝对不吃的食材</h2><div class="chips section">${['香菜','番茄','鸡肉','猪肉','蘑菇','豆腐'].map(x=>chip(x,'avoid|'+x,state.diet.absoluteAvoids.includes(x))).join('')}</div><label class="field">其他忌口（用逗号分隔）<input data-field="custom-avoid" value="${esc(state.diet.absoluteAvoids.filter(x=>!['香菜','番茄','鸡肉','猪肉','蘑菇','豆腐'].includes(x)).join('，'))}" placeholder="输入食材名称"></label></section>${bottom('保存','save-diet')}`;}
function settings(){return `${header('通用设置','/me')}<div class="card"><label class="menu-item"><span>♧</span><span class="grow">消息通知（本地偏好）</span><input class="check" type="checkbox" data-field="notifications" ${check(state.notifications)}></label>${action('info|数据仅保存在当前浏览器。当前没有云端同步，也不上传照片。','♧　隐私设置 ›','menu-item')}${action('info|本地数据包含库存和食记，V0 不自动清除。','♧　缓存与数据 ›','menu-item')}</div><div class="card section">${action('info|一篮 V0 · 本地计算 · 本地数据','ⓘ　关于我们 ›','menu-item')}</div>`;}
function onboardingTop(title,subtitle,back,progress=0){return `<div class="onboarding-top">${link(back,glyph('arrow-left'),'onboarding-back')}${progress?`<div class="onboarding-progress"><i style="width:${progress}%"></i></div>`:''}</div><header class="onboarding-heading"><h1>${title}</h1><p>${subtitle}</p></header>`;}
function onboardingLeaves(){return `<div class="onboarding-leaves" aria-hidden="true">${libraryArt('v5/decorative/plant_02','leaf-left')}${libraryArt('v5/decorative/plant_02','leaf-right')}</div>`;}
function login(){return `<div class="welcome onboarding-welcome"><div class="welcome-hero"><div class="welcome-basket-art" role="img" aria-label="一篮新鲜蔬菜与手绘布巾"></div></div><h1>欢迎来到一篮</h1><p class="welcome-subtitle">好食材，好生活，一篮就够。</p><div class="login-options">${action('info|账号登录尚未接入，可先点开始设置使用本地版本。',glyph('user')+'手机号 / 邮箱登录','button login-phone')}${action('info|微信登录尚未接入，可先点开始设置。',glyph('wechat-logo')+'微信登录','button login-wechat')}${action('info|Apple 登录尚未接入，可先点开始设置。',glyph('apple-logo')+'Apple 登录','button login-apple')}</div><div class="welcome-divider">或</div>${link('/onboarding/profile','开始设置','button welcome-start')}<p class="welcome-footer">一篮 ｜ 好食材 · 好生活 · 一篮就够</p>${link('/basket','先看看','text-button welcome-skip')}<img class="welcome-table-art" src="/assets/library/onboarding/welcome-table.png" alt="" aria-hidden="true"></div>`;}
function onboardingProfile(){
 const art=name=>`<span class="profile-art profile-art-${name}" aria-hidden="true"></span>`;
 const choice=(label,command,selected,image)=>action(command,`<span class="profile-choice-art">${art(image)}</span><span>${label}</span>`,'profile-choice'+(selected?' active':''),`aria-pressed="${selected}"`);
 const allergies=['花生','海鲜','牛奶','鸡蛋','坚果','小麦','大豆'];
 const extra=state.diet.allergies.filter(x=>!allergies.includes(x));
 return `<div class="profile-setup"><header class="profile-intro"><h1>你平时怎么吃？</h1><p>这些习惯，会帮我们算出更合适的一篮。</p>${art('basket')}</header>
 <div class="profile-form"><section><h3>${glyph('users')}平时一般几个人吃饭？</h3><div class="profile-choices">${[[1,'1人'],[2,'2人'],[4,'3–4人'],[5,'5人+']].map(([n,label],i)=>choice(label,'diners|'+n,state.profile.defaultDiners===n,'bowls-'+i)).join('')}</div>${state.profile.defaultDiners>=4?`<small class="profile-estimate">暂按 ${state.profile.defaultDiners} 人估算，每餐都可以调整。</small>`:''}</section>
 <section><h3>${glyph('basket')}通常一次买几天？</h3><div class="profile-choices">${[3,5,7,'flexible'].map((n,i)=>choice(n==='flexible'?'不固定':n+'天','purchase-frequency|'+n,(state.profile.purchaseFrequency??state.cycle.plannedDays)===n,'calendar-'+i)).join('')}</div></section>
 <div class="profile-divider"><span>再补充一点</span><i></i><small>小小信息，<br>带来刚刚好的一篮</small></div>
 <label class="field"><span class="profile-label">${glyph('user')}你怎么称呼呀？</span><input aria-label="昵称" autocomplete="nickname" placeholder="输入你的昵称" maxlength="30" value="${esc(state.profile.nickname==='Demo User'?'':state.profile.nickname)}" data-field="profile" data-id="nickname"></label>
 <section><h3>${glyph('leaf')}过敏注意事项 <small>（可选）</small></h3><div class="profile-allergies">${[...allergies,...extra].map(x=>action('allergy|'+esc(x),`<span>${esc(x)}</span>${state.diet.allergies.includes(x)?glyph('check-circle'):''}`,'chip'+(state.diet.allergies.includes(x)?' active':''),`aria-pressed="${state.diet.allergies.includes(x)}"`)).join('')}<details class="profile-other"><summary>${glyph('plus')}其他</summary><label class="field">其他过敏食材<input aria-label="其他过敏食材" data-field="custom-allergy" maxlength="80" placeholder="输入食材名称，用逗号分隔" value="${esc(extra.join('，'))}"></label></details></div><p class="profile-help">之后搭配食材时，我们会自动避开这些。</p></section>
 <label class="field"><span class="profile-label">${glyph('house')}你平时在哪座城市买菜？ <small>（可选）</small></span><input aria-label="常住城市" autocomplete="address-level2" placeholder="选择或输入城市" maxlength="40" value="${esc(state.profile.city||'')}" data-field="profile" data-id="city"></label></div>
 <footer class="profile-footer">${action('onboard-kitchen','看看我的厨房','button')}${art('board')}<p>好好吃饭<br>好好生活</p></footer></div>`;
}
function onboardingKitchen(){const ids=['wok','stockpot','frying_pan','steamer','rice-cooker','oven','air_fryer','microwave','blender'];return `${onboardingTop('看看你的厨房','拍一张照片，或手动选择你常用的厨具。','/onboarding/profile',66)}<div class="onboarding-kitchen-hero"><img class="kitchen-scene" src="/assets/library/onboarding/kitchen-scene.png" alt="温暖的厨房插画"><label class="button kitchen-photo">${glyph('plus-circle')}拍一张厨房照片<input type="file" accept="image/*" capture="environment" aria-label="厨房照片" data-field="photo" data-id="kitchen"></label></div><p class="kitchen-manual">也可以手动选择</p><h3 class="kitchen-choice-title">我的厨具 <small>（可修改）</small></h3><div class="onboarding-tool-grid">${ids.map(id=>{const t=toolsCatalog.find(t=>t.id===id),selected=state.kitchen.tools.some(t=>t.id===id&&t.available);return action('onboard-tool|'+id,cookwareArt(id)+`<span>${esc(t.name)}</span>`,'onboarding-tool'+(selected?' active':''),`aria-pressed="${selected}"`);}).join('')}</div><label class="row kitchen-stoves"><span class="grow">可同时使用的灶位</span><input class="number" type="number" min="1" max="4" aria-label="灶位数量" data-field="stove" value="${state.kitchen.stoveSlots}"></label><p class="note">按家里实际情况选择，之后也能随时修改。</p><div class="onboarding-bottom">${action('onboard-complete','下一步：开启一篮','button')}</div>${onboardingLeaves()}`;}
function onboardComplete(){const frequency=state.profile.purchaseFrequency??state.cycle.plannedDays;return `${onboardingTop('太好了，可以开始一篮了！','这是为你准备的专属摘要，之后也可以随时修改。','/onboarding/kitchen')}<div class="onboarding-finish-hero">${libraryArt('onboarding/illustration_vegetable_basket','finish-basket','一篮食材')}<p class="basket-letter">好的食物<br>会让平凡的日子<br>闪闪发光<br><span>— 一篮</span></p></div><div class="card onboarding-summary"><p>${glyph('users')}${state.profile.defaultDiners} 人吃</p><p>${glyph('calendar-blank')}${frequency==='flexible'?'采购周期：每次灵活安排':frequency+'天采购一次'}</p><p>${glyph('house')}常住城市：${esc(state.profile.city||'暂未填写')}</p><p>${glyph('cooking-pot')}已选择厨具 ${state.kitchen.tools.filter(t=>t.available).length} 项</p>${state.diet.allergies.length?`<p>${glyph('leaf')}过敏注意：${esc(state.diet.allergies.join('、'))}</p>`:''}</div><div class="onboarding-tip">${glyph('leaf')}<p>饮食偏好可以在挑选每一篮时<br>灵活选择，随时调整。</p></div><div class="onboarding-bottom">${link('/basket/plan','开启第一篮','button')}${link('/basket','稍后再补充','button outline')}<p class="onboarding-closing">从这一篮开始，<br>把日子过成喜欢的样子。</p></div>${onboardingLeaves()}`;}

function sheetBody(){if(sheet==='plan-wanted')return `<p class="note">点选想吃的菜，再点一次可取消。</p><div class="plan-wanted-grid">${planWantedRecipes().map(planWantedCard).join('')}</div><div class="sheet-footer">${action('close',`完成 · 已选 ${state.cycle.anchorWantedDishIds.length} 道`,'button')}</div>`;if(sheet==='edit-cycle')return `<p class="note">调整这一篮的安排，保留已选偏好和食材。</p><div class="cycle-edit-fields"><label>开始日期<input type="date" name="startDate" required value="${basketDateInput()}"></label><label>这篮准备几天<input type="number" name="plannedDays" min="1" max="30" step="1" required value="${state.cycle.plannedDays}"></label><label>用餐人数<input type="number" name="diners" min="1" max="20" step="1" required value="${state.profile.defaultDiners}"></label><label>预计在家做几顿<input type="number" name="expectedMeals" min="1" max="30" step="1" required value="${state.cycle.expectedMeals}"></label></div><p class="note">保存后会更新未购买的建议；已买到的食材保持不变。</p><div class="cycle-edit-actions">${action('close','取消','button secondary')}${action('save-cycle',busy?'正在更新…':'保存修改','button',busy?'disabled':'')}</div>`;if(sheet==='capture-add'||sheet?.startsWith('capture-replace|')){const current=captureItems.find(i=>i.id===sheet.split('|')[1]);return `<p class="note">${current?'选择正确的食材，只替换这一项；单位不同时会重置数量，请核对。':'选择这次实际买到的食材，数量可以随后调整。'}</p><div class="capture-picker">${[...new Set(Object.values(ingredients).map(i=>i.category))].map(category=>`<section><h3>${esc(category)}</h3><div class="ingredient-grid">${Object.values(ingredients).filter(i=>i.category===category).map(i=>action('capture-pick|'+i.id,ingredientTile(i.id,current?.ingredientId===i.id?'✓ 当前食材':unitInfo(state,i.id).unit),'capture-pick-card'+(current?.ingredientId===i.id?' active':''),`aria-pressed="${current?.ingredientId===i.id}"`)).join('')}</div></section>`).join('')}</div>`;}if(sheet==='capture-tips')return '<p class="note">把小票铺平，保持光线充足，尽量拍全名称与数量。食材可分开摆放，避免包装遮住主体。</p><p class="note section">目前照片仅供你核对，自动识别尚未接入。已填写的清单会保留，重新拍摄不会覆盖。</p>';if(sheet==='capture-example-confirm')return `<p class="note">载入示例会替换当前未入库清单，是否继续？</p>${action('capture-example-load','替换为示例清单','button')}`;if(sheet==='suggestion-add')return `<p class="note">只补充建议清单，确认实际购买后才入库。</p><div class="ingredient-grid section">${Object.keys(ingredients).filter(id=>!state.suggestions.some(i=>i.ingredientId===id&&i.purchaseQty>0)).map(id=>action('add-suggestion|'+id,ingredientTile(id,ingredients[id].unit))).join('')}</div>`;if(sheet==='wanted')return `<input class="search" placeholder="搜索想吃的菜" data-field="wanted-search" value="${esc(search)}"><div class="chips section">${['全部','中式','日式','西式'].map(s=>chip(s,'wanted-filter|'+s,wantedFilter===s)).join('')}</div>${state.wanted.filter(w=>w.title.includes(search)&&(wantedFilter==='全部'||recipe(w.linkedRecipeId)?.cuisine===wantedFilter)).map(w=>`<label class="item-row"><span class="wanted-thumbnail">${food(recipe(w.linkedRecipeId))}</span><span class="grow">${esc(w.title)}${!w.linkedRecipeId?'<small> · 暂未关联验证菜谱</small>':''}</span><input type="checkbox" class="check" data-field="wanted-check" data-id="${w.id}" ${check(wantedDraft.includes(w.id))} ${!w.linkedRecipeId?'disabled':''}></label>`).join('')}<div class="sheet-footer">${action('wanted-done',`确定 · 已选 ${wantedDraft.length} 道`,'button')}</div>`;
if(sheet==='purchase')return `<p class="note">只录入勾选的实际购买量。未买到的继续保留在采购清单。</p>${state.purchases.filter(p=>p.checked&&p.state!=='stock').map(p=>`<div class="item-row">${icon(p.ingredientId)}<span class="grow">${ingredients[p.ingredientId].name}</span><b>${displayQty(state,p.ingredientId,p.actualQty)}</b></div>`).join('')}<div class="sheet-footer">${action('purchase-commit','确认实际购买量并入库','button')}</div>`;
if(sheet==='capture-confirm')return `<p class="note">以下是你核对过的实际购买食材：</p>${captureItems.map(i=>`<p class="item-row">${ingredients[i.ingredientId].name}　${displayQty(state,i.ingredientId,i.actualQty)}</p>`).join('')}<div class="sheet-footer">${action('capture-commit','确认入库','button')}</div>`;
if(sheet==='usage')return `<p class="note">请确认实际用量，只有这一步会扣减库存。常备调料不按克扣减。</p>${usage.filter(i=>!isPantry(i.ingredientId)).map(i=>`<div class="item-row">${icon(i.ingredientId)}<div class="grow"><h3>${ingredients[i.ingredientId].name}</h3><small>库存 ${stockLabel(state,i.ingredientId)}</small></div>${qty(i.qty,'usage',i.ingredientId,i.unit)}</div>`).join('')}<label class="item-row"><input class="check" type="checkbox" data-field="save-record" ${check(saveRecord)}>同时保存到「吃过的」</label><div class="sheet-footer">${action('complete','确认实际用量，完成这餐','button')}</div>`;
if(sheet==='adjust'){const choices=directionOptions(state),c=adjust.constraints;const illustrated=(label,command,active,art)=>action(command,art+`<span>${esc(label)}</span>`,'direction-choice'+(active?' active':''),`aria-pressed="${active}"`);const mealArt={'米饭配菜':'rice_meal','盖饭拌饭':'japanese','面条米粉':'noodles','汤粥':'soup','沙拉拌碗':'vegetable'};return `<div class="direction-body"><section class="direction-section"><h3>${glyph('users')}这顿几个人吃？</h3><div class="diners-options">${[1,2,3,4].map(n=>chip(n+'人','instant-diners|'+n,adjust.diners===n)).join('')}</div></section><section class="direction-section"><h3>${glyph('fork-knife')}这顿想吃什么？</h3><div class="illustrated-options meal-options">${[...choices.mealTypes,'还没想好'].map(t=>illustrated(t.replace('盖饭拌饭','盖饭/拌饭').replace('面条米粉','面条/米粉').replace('汤粥','汤/粥').replace('沙拉拌碗','沙拉/拌碗'),'meal-type|'+t,c.mealType===t,mealArt[t]?libraryArt('v5/cuisine/'+mealArt[t],'direction-art'):glyph('bowl-food','direction-art'))).join('')}</div></section><section class="direction-section"><h3>${glyph('bowl-food')}今天想吃什么菜系？</h3><div class="illustrated-options cuisine-options">${choices.cuisines.map(t=>illustrated(t,'instant-cuisine|'+t,c.cuisines.includes(t),cuisineArt(t))).join('')}</div></section><section class="direction-section"><h3>${glyph('clock')}这顿想省什么？</h3><div class="operation-options">${['省时间','少洗锅','少切配','一锅出'].map(t=>illustrated(t,'operation|'+t,c.operationPrefs.includes(t),glyph({'省时间':'clock','少洗锅':'cooking-pot','少切配':'knife','一锅出':'cooking-pot'}[t]))).join('')}</div><div class="time-options">${chip('不限','time|180',c.timeLimit===180)}${[20,30,60].map(n=>chip(n+'分钟内','time|'+n,c.timeLimit===n)).join('')}</div></section><section class="direction-section"><h3>${glyph('leaf')}口味</h3><div class="flavor-options">${choices.flavors.map(t=>illustrated(t,'instant-flavor|'+t,c.flavors.includes(t),flavorArt(t))).join('')}</div></section><section class="direction-section"><h3>${glyph('basket')}食材</h3><div class="stock-options">${['现有食材优先','可以补买 1–2 样'].map(t=>chip(t,'policy|'+t,t==='现有食材优先'?!allowsTopUp({meal:adjust}):allowsTopUp({meal:adjust}))).join('')}</div></section></div><div class="sheet-footer">${action('reset-adjust','重置','text-button')}${action('apply-adjust','按这个重新推荐','button')}</div>`;}
if(sheet==='kitchen-scan')return `<p class="notice">Mock 示例候选，未识别真实照片。请核对后保存。</p>${kitchenCandidates.map((t,n)=>`<label class="item-row"><span class="grow">${esc(t.name)}</span><input aria-label="${esc(t.name)}识别数量" class="number" type="number" min="0" max="10" data-field="kitchen-candidate" data-id="${n}" value="${t.quantityCandidate}"></label>`).join('')}<div class="sheet-footer">${action('confirm-kitchen','确认厨具候选','button')}</div>`;
if(sheet?.startsWith('lots|')){const id=sheet.split('|')[1];if(isPantry(id))return `<p class="note">常备调料按家里的实际情况记录，不随每顿精确扣减。</p><div class="chips section">${['有','快没了','没有'].map(status=>chip(status,'pantry|'+id+'|'+status,pantryStatus(state,id)===status)).join('')}</div>`;return (id==='milk'?`<div class="chips section">${chip('盒','milk-unit|carton',state.unitPrefs.milk!=='bottle')}${chip('瓶','milk-unit|bottle',state.unitPrefs.milk==='bottle')}</div><p class="note">按包装规格折算，切换不会改变库存总量。</p>`:'')+state.stock.filter(l=>l.ingredientId===id&&l.qty>0).map(l=>`<div class="item-row"><div class="grow"><h3>${displayQty(state,id,l.qty)}</h3><small>${date(l.acquiredAt)} 购入 · ${l.storage}</small></div></div>`).join('');}
if(sheet==='bought')return state.purchases.filter(p=>p.state==='stock').map(p=>`<p class="item-row">${ingredients[p.ingredientId].name}　${displayQty(state,p.ingredientId,p.actualQty)}　✓ 已入库</p>`).join('')||'<p class="empty">尚未确认采购</p>';
return '';}
// Draft choices only change button state: keep the sheet, images, focus and scroll in place.
function syncDirectionChoices(panel){for(const button of panel.querySelectorAll('[data-action]')){const [action,value]=button.dataset.action.split('|'),c=adjust.constraints;let active;switch(action){case 'instant-diners':active=adjust.diners===Number(value);break;case 'instant-cuisine':active=c.cuisines.includes(value);break;case 'instant-flavor':active=c.flavors.includes(value);break;case 'meal-type':active=c.mealType===value;break;case 'time':active=c.timeLimit===Number(value);break;case 'operation':active=c.operationPrefs.includes(value);break;case 'policy':active=value==='现有食材优先'?!allowsTopUp({meal:adjust}):allowsTopUp({meal:adjust});break;default:continue;}button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));}}
function render(){if(route!=='/basket/plan')planDateStart=null;const directionPanel=sheet==='adjust'&&app.querySelector('.direction-sheet');if(directionPanel){syncDirectionChoices(directionPanel);return;}const dateScroll=app.querySelector('.plan-date-strip')?.scrollLeft;const carouselLeft=app.querySelector('.carousel')?.scrollLeft||0;let body;try{body=route==='/basket'?basket():route==='/basket/plan'?plan():route==='/basket/recommendation'?recommendation():route==='/basket/shopping'?shopping():route==='/basket/capture'?capture():route==='/cook'?cook():route.startsWith('/cook/tutorial/')?tutorial():route==='/journal'?journal():route==='/journal/camera'?camera():route==='/journal/capture-confirm'?dishConfirm():route==='/me'?me():route==='/me/profile'?profile():route==='/me/diet'?diet():route==='/me/settings'?settings():route==='/me/kitchen'?kitchen():route==='/me/kitchen/add'?addTool():route.startsWith('/me/kitchen/cookware/')?editTool():route==='/login'?login():route==='/onboarding/profile'?profile(true):route==='/onboarding/kitchen'?kitchen(true):route==='/onboarding/complete'?onboardComplete():`${header('页面不存在','/basket')}`;}catch(e){body=`${header('暂时无法显示','/basket')}<p>${esc(e.message)}</p>`;}const l1=['/basket','/cook','/journal','/me'].includes(route);app.innerHTML=`<div class="app"><main class="page ${l1?'typography-preview':'plain'} ${route==='/login'||route.startsWith('/onboarding/')?'onboarding-page':route==='/basket'?'basket-page':route==='/basket/plan'?'plan-page':route==='/basket/recommendation'?'recommendation-page':route==='/cook'?'cook-page':route.startsWith('/cook/tutorial/')?'tutorial-page':''}" ${sheet?'inert':''}>${body}</main>${l1?nav():''}${sheet?`<div class="sheet-backdrop"><section class="sheet ${sheet==='adjust'?'direction-sheet':''}" role="dialog" aria-modal="true" aria-label="${sheet==='adjust'?'换个方向':sheet==='usage'?'确认实际用量':'确认与选择'}"><div class="handle"></div><div class="sheet-head"><h2>${({'edit-cycle':'修改本轮安排','suggestion-add':'添加其他食材','plan-wanted':'特别想吃','wanted':'从想吃的挑','purchase':'确认实际购买','capture-confirm':'确认实际购买','capture-add':'选择买到的食材','capture-tips':'拍摄小贴士','capture-example-confirm':'替换草稿','usage':'确认实际用量','adjust':'换个方向','kitchen-scan':'确认厨房识别','bought':'已确认购买'})[sheet]||(sheet.startsWith('capture-replace|')?'更换食材':ingredients[sheet.split('|')[1]]?.name)||'详情'}</h2>${action('close','×','',`aria-label="关闭弹层"`)}</div>${sheetBody()}</section></div>`:''}${toast?`<div class="toast" role="status">${esc(toast)}</div>`:''}</div>`;const dateStrip=app.querySelector('.plan-date-strip');if(dateStrip){const selected=dateStrip.querySelector('.active');dateStrip.scrollLeft=dateScroll??Math.max(0,(selected?.offsetLeft||0)-dateStrip.clientWidth/2+22);}if(route==='/cook'&&carouselLeft)app.querySelector('.carousel')?.scrollTo({left:carouselLeft});}
function toggle(array,value){return array.includes(value)?array.filter(x=>x!==value):[...array,value];}
function editQuantity(field,id,value){const n=Math.round(number(value)*unitInfo(state,id).size*100)/100;if(field==='suggestion'){const i=state.suggestions.find(i=>i.ingredientId===id);if(i.locked)return;i.purchaseQty=n;}if(field==='purchase')state.purchases.find(i=>i.ingredientId===id&&i.state!=='stock').actualQty=n;if(field==='usage')usage.find(i=>i.ingredientId===id).qty=n;}
async function generate(){const issue=basketPlanningIssue(state);if(issue){document.querySelector('#planner-setup')?.scrollIntoView({behavior:'smooth',block:'center'});throw new Error(issue);}busy=true;render();try{const locked=state.suggestions.filter(i=>i.locked);const result=await ai.planBasket(state);state.suggestions=result.ingredientSuggestions.map(i=>locked.find(l=>l.ingredientId===i.ingredientId)||i);tradeoffs=result.tradeoffs;state.planningInsights=result.planningInsights||[];state.planningMessages=result.planningMessages||[];state.suggestionSource=result.meta?.source||'mock';save();go('/basket/recommendation');}finally{busy=false;render();}}
