function imageData(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const im=new Image();im.onload=()=>{const scale=Math.min(1,1000/im.width);const canvas=document.createElement('canvas');canvas.width=im.width*scale;canvas.height=im.height*scale;canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',.75));};im.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('图片无法打开，请使用 JPG 或 PNG'));};im.src=url;});}
