window.addEventListener('yilan-visual-ready',()=>render());

// Inventory edited in another tab must invalidate in-flight and cached recommendations.
window.addEventListener('storage',async event=>{if(event.key!==KEY||!event.newValue)return;let next;try{next=JSON.parse(event.newValue);if(next?.version!==1)return;normalizeProductState(next);}catch{return;}state=next;recommendationEpoch++;rankSignature='';render();if(route==='/cook')await refreshCards();});
